19: export class ListEspaciosAcademicosComponent implements OnInit {
20:   displayedColumns: string[] = ['nombre', 'codigo', 'estado', 'acciones'];
21:   espacios_academicos: EspacioAcademico[] = [];
22:   estados_aprobacion!: EstadoAprobacion[];
23:   IsAdmin!: boolean;
24:   dataSource!: MatTableDataSource<EspacioAcademico>;
25:   @ViewChild(MatPaginator) paginator!: MatPaginator;
26: 
27:   constructor(
28:     private translate: TranslateService,
29:     private espaciosAcademicosService: EspaciosAcademicosService,
30:     private popUpManager: PopUpManager,
31:     private autenticationService: ImplicitAutenticationService,
32:     private router: Router
33:   ) {}
34: 
35:   async ngOnInit() {
36:     this.autenticationService.getRole().then((rol: any) => {
37:       const r1 = rol.find((role: string) => role == ROLES.ADMIN_SGA);
38:       const r2 = rol.find((role: string) => role == ROLES.ASIS_PROYECTO);
39:       if (r1) {
40:         this.IsAdmin = true;
41:       } else if (r2) {
42:         this.IsAdmin = false;
43:       }
44:     });
45: 
46:     await this.cargarDatosTabla();
47:   }
48: 
49:   async cargarDatosTabla() {
50:     try {
51:       await this.cargarEspaciosAcademicos();
52:       await this.cargarEstadosAprobacion();
53:     } catch (error) {
54:       this.popUpManager.showErrorToast('ERROR GENERAL' + error);
55:     }
56: 
57:     this.espacios_academicos.forEach((espacio) => {
58:       this.ajustarBotonesSegunEstado(espacio);
59:     });
60: 
61:     this.dataSource = new MatTableDataSource<EspacioAcademico>(
62:       this.espacios_academicos
63:     );
64:     this.dataSource.paginator = this.paginator;
65:   }
66: 
67:   async cargarEspaciosAcademicos() {
68:     return new Promise((resolve, reject) => {
69:       this.espaciosAcademicosService
70:         .get(
71:           'espacio-academico?query=espacio_academico_padre,activo:true&limit=0'
72:         )
73:         .subscribe(
74:           (response: any) => {
75:             this.espacios_academicos = response['Data'];
76:             resolve(true);
77:           },
78:           (error) => {
79:             reject(error);
80:           }
81:         );
82:     });
83:   }
84: 
85:   async cargarEstadosAprobacion() {
86:     return new Promise((resolve, reject) => {
87:       this.espaciosAcademicosService
88:         .get('estado-aprobacion?query=activo:true&limit=0')
89:         .subscribe(
90:           (response: any) => {
91:             this.estados_aprobacion = response['Data'];
92:             resolve(true);
93:           },
94:           (error) => {
95:             reject(error);
96:           }
97:         );
98:     });
99:   }
100: 
101:   ajustarBotonesSegunEstado(espacio: any) {
102:     const estado = this.estados_aprobacion.find(
103:       (estado) => estado._id == espacio.estado_aprobacion_id
104:     );
105:     if (estado) {
106:       espacio['estado'] = estado.nombre;
107:       if (this.IsAdmin) {
108:         let accion, tipo;
109:         if (estado.codigo_abreviacion == STD.IS_APRV) {
110:           accion = ACTIONS.VIEW;
111:           tipo = 'ver';
112:         } else {
113:           accion = ACTIONS.EDIT_PART;
114:           tipo = 'editar';
115:         }
116:         espacio['gestion'] = { value: accion, type: tipo, disabled: false };
117:         espacio['enviar'] = {
118:           value: undefined,
119:           type: 'enviar',
120:           disabled: true,
121:         };
122:       } else {
123:         let accion, tipo;
124:         if (
125:           estado.codigo_abreviacion == STD.IN_EDIT ||
126:           estado.codigo_abreviacion == STD.NOT_APRV
127:         ) {
128:           accion = ACTIONS.EDIT;
129:           tipo = 'editar';
130:         } else {
131:           accion = ACTIONS.VIEW;
132:           tipo = 'ver';
133:         }
134:         espacio['gestion'] = { value: accion, type: tipo, disabled: false };
135:         const siEnviar = estado.codigo_abreviacion == STD.IN_EDIT;
136:         espacio['enviar'] = {
137:           value: undefined,
138:           type: 'enviar',
139:           disabled: !siEnviar,
140:         };
141:       }
142:     }
143:   }
144: 
145:   aplicarFiltro(event: Event) {
146:     const filterValue = (event.target as HTMLInputElement).value;
147:     this.dataSource.filter = filterValue.trim().toLowerCase();
148: 
149:     if (this.dataSource.paginator) {
150:       this.dataSource.paginator.firstPage();
151:     }
152:   }
153: 
154:   enviaraRevision(id: string) {
155:     const espacio: any = this.espacios_academicos.filter(
156:       (espacio: any) => espacio._id === id
157:     );
158:     let espacio_edit = espacio[0];
159: 
160:     this.popUpManager
161:       .showPopUpGeneric(
162:         this.translate.instant('espacios_academicos.espacios_academicos'),
163:         this.translate.instant('espacios_academicos.enviar_revision_pregunta'),
164:         MODALS.INFO,
165:         true
166:       )
167:       .then((action) => {
168:         if (action.value) {
169:           espacio_edit.estado_aprobacion_id = this.estados_aprobacion.find(
170:             (estado) => estado.codigo_abreviacion == STD.IN_REV
171:           )?._id;
172:           this.espaciosAcademicosService
173:             .put('espacio-academico/' + id, espacio_edit)
174:             .subscribe(
175:               (resp: any) => {
176:                 if (resp.Status == '200') {
177:                   this.popUpManager.showSuccessAlert(
178:                     this.translate.instant(
179:                       'espacios_academicos.enviar_revision_ok'
180:                     )
181:                   );
182:                   this.recargarEspaciosAcademicos();
183:                 } else {
184:                   this.popUpManager.showErrorAlert(
185:                     this.translate.instant(
186:                       'espacios_academicos.enviar_revision_fallo'
187:                     )
188:                   );
189:                 }
190:               },
191:               (err) => {
192:                 this.popUpManager.showErrorAlert(
193:                   this.translate.instant(
194:                     'espacios_academicos.enviar_revision_fallo'
195:                   )
196:                 );
197:               }
198:             );
199:         }
200:       });
