204:     try {
205:       await this.cargarDatosTabla();
206:     } catch (error) {
207:       this.popUpManager.showPopUpGeneric(
208:         this.translate.instant('espacios_academicos.consulta_espacios'),
209:         this.translate.instant('ERROR.sin_informacion_en') +
210:           ': <b>' +
211:           this.translate.instant('espacios_academicos.espacios_academicos') +
