1: import { Component, OnInit } from '@angular/core';
2: import { FormBuilder, FormGroup, Validators } from '@angular/forms';
3: import { LangChangeEvent, TranslateService } from '@ngx-translate/core';
4: import { PopUpManager } from 'src/app/managers/popUpManager';
5: import { ProyectoAcademicoService } from 'src/app/services/proyecto_academico.service';
6: import { ParametrosService } from 'src/app/services/parametros.service';
7: import { EspaciosAcademicosService } from 'src/app/services/espacios_academicos.service';
8: import { NewNuxeoService } from 'src/app/services/new_nuxeo.service';
9: import { ImplicitAutenticationService } from 'src/app/services/implicit_autentication.service';
10: import { AgrupacionEspacios } from 'src/app/models/agrupacion_espacios';
11: import { EspacioAcademico } from 'src/app/models/espacio_academico';
12: import { EstadoAprobacion, STD } from 'src/app/models/estado_aprobacion';
13: import { MODALS, ROLES } from 'src/app/models/diccionario';
14: import { ActivatedRoute, Router } from '@angular/router';
15: import { EspacioAcademicoMidService } from 'src/app/services/espacio_academico_mid.service';
16: 
17: @Component({
18:   selector: 'app-form-espacios-academicos',
19:   templateUrl: './form-espacios-academicos.component.html',
20:   styleUrls: ['./form-espacios-academicos.component.scss'],
21: })
22: export class FormEspaciosAcademicosComponent implements OnInit {
23:   agrupacionEspacios: AgrupacionEspacios[] = [];
24:   espaciosAcademicos: EspacioAcademico[] = [];
25:   espaciosRequeridos: EspacioAcademico[] = [];
26:   estadosAprobacion!: EstadoAprobacion[];
27:   niveles!: any[];
28:   subNivelesPosgrado!: any[];
29:   subNivelesPregrado!: any[];
30:   subNiveles!: any[];
31:   proyectos: any[] = [];
32:   tipos!: any[];
33:   clases!: any[];
34:   enfoques!: any[];
35:   nivelSeleccionado!: number;
36:   subNivelSeleccionado!: number;
37:   proyectosSelect!: any[];
38:   espacioEdicion!: EspacioAcademico;
39: 
40:   inputBoxColor: string = 'white';
41:   agrupacionFacultadId!: string;
42:   archivosSoporte: any[] = [];
43:   accion!: String;
44:   editar!: boolean;
45:   visualizar!: boolean;
46:   camposDisabled: boolean = false;
47:   modificandoEspacio: boolean = false;
48:   readonly horasCredito: number = 48;
49:   valorHorasTotal: number = 0;
50:   mensajeTotalHoras!: String;
51:   IsAdmin!: boolean;
52:   btnAgrupaciondisabled: boolean = false;
53: 
54:   formStep1!: FormGroup;
55:   formStep2!: FormGroup;
56:   formStep3!: FormGroup;
57: 
58:   formProyecto = this.fb.group({
59:     nivel: ['', Validators.required],
60:     sub_nivel: ['', Validators.required],
61:     proyecto_curricular: ['', Validators.required],
62:   });
63: 
64:   formEspacioAcademico = this.fb.group({
65:     nombre: ['', Validators.required],
66:     codigo: ['', Validators.required],
67:     codigo_abreviacion: ['', Validators.required],
68:     plan_estudios: ['', [Validators.required, Validators.min(0)]],
69:     tipo: ['', Validators.required],
70:     clase: ['', Validators.required],
71:     enfoque: ['', Validators.required],
72:     creditos: ['', [Validators.required, Validators.min(1)]],
73:     espacio_modular: ['', Validators.required],
74:     agrupacion_espacios: ['', Validators.required],
75:     agrupacion_espacios_color: [''],
76:     htd: ['', [Validators.required, Validators.min(0)]],
77:     htc: ['', [Validators.required, Validators.min(0)]],
78:     hta: ['', [Validators.required, Validators.min(0)]],
79:     total: ['', Validators.min(0)],
80:     grupos: [''],
81:     espacios_requeridos: [''],
82:   });
83: 
84:   formSoportes = this.fb.group({
85:     soporte: ['', Validators.required],
86:     aprobado: [''],
87:     observaciones: [''],
88:   });
89: 
90:   constructor(
91:     private translate: TranslateService,
92:     private fb: FormBuilder,
93:     private projectService: ProyectoAcademicoService,
94:     private parametrosService: ParametrosService,
95:     private espaciosAcademicosService: EspaciosAcademicosService,
96:     private gestorDocumentalService: NewNuxeoService,
97:     private espacioAcademicoMidService: EspacioAcademicoMidService,
98:     private autenticationService: ImplicitAutenticationService,
99:     private popUpManager: PopUpManager,
100:     private activatedRoute: ActivatedRoute,
101:     private readonly router: Router
102:   ) {}
103: 
104:   async ngOnInit() {
105:     this.autenticationService.getRole().then((rol: any) => {
106:       const r1 = rol.find((role: string) => role == ROLES.ADMIN_SGA);
107:       const r2 = rol.find((role: string) => role == ROLES.ASIS_PROYECTO);
108:       if (r1) {
109:         this.IsAdmin = true;
110:       } else if (r2) {
111:         this.IsAdmin = false;
112:       }
113:     });
114: 
115:     this.formStep1 = this.formProyecto;
116:     this.formStep2 = this.formEspacioAcademico;
117:     this.formStep3 = this.formSoportes;
118: 
119:     await this.cargarDatosSelect();
120:     this.gestorDocumentalService.clearLocalFiles();
121: 
122:     this.activatedRoute.params.subscribe((params) => {
123:       this.accion = params['accion'];
124:       const espacio: any = this.espaciosAcademicos.filter(
125:         (espacio: any) => espacio._id === params['elemento']
126:       );
127:       if (espacio) {
128:         this.espacioEdicion = espacio[0];
129:       }
130:     });
131: 
132:     this.manejoDeAcciones();
133:   }
134: 
135:   manejoDeAcciones() {
136:     if (this.accion == 'crear') {
137:       this.modificandoEspacio = true;
138:     } else if (this.accion == 'editar') {
139:       this.modificandoEspacio = true;
140:       this.editar = true;
141:       this.cargarFormulario(this.espacioEdicion);
142:     } else if (this.accion == 'visualizar') {
143:       this.visualizar = true;
144:       this.cargarFormulario(this.espacioEdicion);
145:     }
146: 
147:     if (this.visualizar || this.editar) {
148:       this.camposDisabled = true;
149:     }
150:   }
151: 
152:   async cargarDatosSelect() {
153:     try {
154:       await this.cargarNiveles();
155:       await this.cargarProyectos();
156:       await this.cargarTipos();
157:       await this.cargarClases();
158:       await this.cargarEnfoques();
159:       await this.cargarEspaciosAcademicos();
160:       await this.cargarEstadosAprobacion();
161:     } catch (error) {
162:       this.popUpManager.showErrorToast('ERROR GENERAL' + error);
163:     }
164:   }
165: 
166:   async cargarNiveles(): Promise<any> {
167:     return new Promise((resolve, reject) => {
168:       this.projectService
169:         .get('nivel_formacion?query=Activo:true&sortby=Id&order=asc&limit=0')
170:         .subscribe(
171:           (response: any) => {
172:             if (Object.keys(response[0]).length > 0) {
173:               this.niveles = response.filter(
174:                 (nivel: any) => nivel.NivelFormacionPadreId == undefined
175:               );
176:               this.subNivelesPregrado = response.filter(
177:                 (nivel: any) =>
178:                   nivel.NivelFormacionPadreId &&
179:                   nivel.NivelFormacionPadreId.Id == 1
180:               );
181:               this.subNivelesPosgrado = response.filter(
182:                 (nivel: any) =>
183:                   nivel.NivelFormacionPadreId &&
184:                   nivel.NivelFormacionPadreId.Id == 2
185:               );
186:               this.subNiveles = [
187:                 ...this.subNivelesPosgrado,
188:                 ...this.subNivelesPregrado,
