1: import { Injectable } from '@angular/core';
2: import { CanActivate, RouterStateSnapshot, ActivatedRouteSnapshot } from '@angular/router';
3: import { TranslateService } from '@ngx-translate/core';
4: import { PopUpManager } from 'src/app/managers/popUpManager';
5: 
6: @Injectable({ providedIn: 'root' })
7: export class AuthGuard implements CanActivate {
8:   constructor(
9:     private popUpManager: PopUpManager,
10:     private translate: TranslateService
11:   ) {}
12: 
13:   canActivate(_route: ActivatedRouteSnapshot, _state: RouterStateSnapshot): boolean {
14:     const menuItems = readMenuItemsFromStorage('menu');
15:     const targetPath = getGlobalPath(); // ✅ Single-SPA safe
16: 
17:     // 1) Aplana URLs permitidas desde el menú (recursivo)
18:     const allowed = collectAllowedUrls(menuItems);
19: 
20:     // 2) Estrategia de validación:
21:     // - exacta: permite /ruta exacta
22:     // - prefijo: permite /ruta y cualquier subruta /ruta/...
23:     const ok = isAllowed(targetPath, allowed, { allowSubroutes: true });
24: 
25:     if (ok) return true;
26: 
27:     this.popUpManager.showErrorAlert(
28:       this.translate.instant('ERROR.rol_insuficiente_titulo')
29:     );
30:     return false;
31:   }
32: }
33: 
34: /** Lee "menu" desde localStorage en JSON plano o base64(JSON). */
35: function readMenuItemsFromStorage(key: string): any[] {
36:   const raw = localStorage.getItem(key);
37:   if (!raw) return [];
38: 
39:   const parsed = tryParseJson(raw) ?? tryParseJson(atobSafe(raw));
40:   const items = extractMenuItems(parsed);
41: 
42:   return Array.isArray(items) ? items : [];
43: }
44: 
45: function tryParseJson(s: string | null): any | null {
46:   if (!s) return null;
47:   try { return JSON.parse(s); } catch { return null; }
48: }
49: 
50: function atobSafe(s: string): string | null {
51:   try { return atob(s); } catch { return null; }
52: }
53: 
54: /** Soporta menús envueltos: array directo, {Opciones}, {menu}, {data}, etc. */
55: function extractMenuItems(menu: any): any[] {
56:   if (!menu) return [];
57:   if (Array.isArray(menu)) return menu;
58:   if (Array.isArray(menu?.Opciones)) return menu.Opciones;
59:   if (Array.isArray(menu?.menu)) return menu.menu;
60:   if (Array.isArray(menu?.data)) return menu.data;
61:   if (Array.isArray(menu?.data?.Opciones)) return menu.data.Opciones;
62:   return [];
63: }
64: 
65: /**Single-SPA: toma la ruta global real (pathname o hash routing). */
66: function getGlobalPath(): string {
67:   const hash = window.location.hash || '';
68:   if (hash.startsWith('#/')) return normalizePath(hash.slice(1));
69:   return normalizePath(window.location.pathname || '/');
70: }
71: 
72: /** Normaliza: quita query/hash/matrix, asegura '/', quita '/' finales. */
73: function normalizePath(path: string): string {
74:   let p = (path || '/').split('?')[0].split('#')[0];
75:   p = p.split(';')[0].trim();
76:   if (!p.startsWith('/')) p = '/' + p;
77:   if (p.length > 1) p = p.replace(/\/+$/, '');
78:   return p;
79: }
80: 
81: /** Recorre menú y devuelve una lista de URLs normalizadas (solo las que existan). */
82: function collectAllowedUrls(menuItems: any[]): string[] {
83:   const out: string[] = [];
84: 
85:   const walk = (items: any[]) => {
86:     for (const it of items) {
87:       const url = (it?.Url ?? it?.url ?? '').toString().trim();
88:       if (url) out.push(normalizePath(url));
89: 
90:       const children = it?.Opciones ?? it?.opciones ?? [];
91:       if (Array.isArray(children) && children.length) walk(children);
92:     }
93:   };
94: 
95:   walk(menuItems);
96: 
97:   // elimina duplicados
98:   return Array.from(new Set(out));
99: }
100: 
101: function isAllowed(
102:   target: string,
103:   allowedUrls: string[],
104:   opts: { allowSubroutes: boolean }
105: ): boolean {
106:   if (!allowedUrls.length) return false;
107: 
108:   // exact match
109:   if (allowedUrls.includes(target)) return true;
110: 
111:   // prefijo (subrutas)
112:   if (opts.allowSubroutes) {
113:     return allowedUrls.some(u => u !== '/' && target.startsWith(u + '/'));
114:   }
115: 
116:   return false;
117: }

